import { gunzipSync } from 'node:zlib'

const source = 'https://cdn.jsdelivr.net/gh/Mar-7th/StarRailRes@master/index_new/cn/'

function decode<T>(value: string): T {
  return JSON.parse(gunzipSync(Buffer.from(value, 'base64')).toString('utf8')) as T
}

interface StarRailStat {
  base: number
  step: number
}

interface StarRailPromotion {
  hp: StarRailStat
  atk: StarRailStat
  def: StarRailStat
  spd?: StarRailStat
}

interface StarRailProperty {
  type: string
  value: number
}

interface StarRailCharacter {
  id: string
  name: string
  rarity: number
  path: string
  element: string
  icon: string
  max_sp?: number
  ranks: string[]
  skills: string[]
  skill_trees: string[]
}

interface StarRailLightCone {
  id: string
  name: string
  rarity: number
  path: string
  icon: string
}

interface StarRailSkill {
  id: string
  name: string
  type: string
  type_text: string
  icon: string
  levels?: { properties: StarRailProperty[] }[]
}

interface StarRailSkillTree {
  id: string
  name: string
  icon: string
  anchor: string
  level_up_skills: { id: string; num: number }[]
  levels: { properties: StarRailProperty[] }[]
}

interface StarRailPromotionEntry {
  id: string
  values: StarRailPromotion[]
}

interface StarRailLightConeRank {
  id: string
  skill: string
  properties: StarRailProperty[][]
}

const characters = ''
const characterPromotionsData = ''
const characterSkillsData = ''
const characterSkillTreesData = ''
const lightConesData = ''
const lightConePromotionsData = ''
const lightConeRanksData = ''
const relicsMetadata = {
  source: `${source}relics.json`,
  set_id: '101',
  entries: [
    { id: '31011', set_id: '101', name: '过客的逢春木簪', rarity: 2, type: 'HEAD', max_level: 6, main_affix_id: '21', sub_affix_id: '2', icon: 'icon/relic/101_0.png' },
    { id: '31012', set_id: '101', name: '过客的游龙臂鞲', rarity: 2, type: 'HAND', max_level: 6, main_affix_id: '22', sub_affix_id: '2', icon: 'icon/relic/101_1.png' },
    { id: '31013', set_id: '101', name: '过客的残绣风衣', rarity: 2, type: 'BODY', max_level: 6, main_affix_id: '23', sub_affix_id: '2', icon: 'icon/relic/101_2.png' },
    { id: '31014', set_id: '101', name: '过客的冥途游履', rarity: 2, type: 'FOOT', max_level: 6, main_affix_id: '24', sub_affix_id: '2', icon: 'icon/relic/101_3.png' },
    { id: '61011', set_id: '101', name: '过客的逢春木簪', rarity: 5, type: 'HEAD', max_level: 15, main_affix_id: '51', sub_affix_id: '5', icon: 'icon/relic/101_0.png' },
    { id: '61012', set_id: '101', name: '过客的游龙臂鞲', rarity: 5, type: 'HAND', max_level: 15, main_affix_id: '52', sub_affix_id: '5', icon: 'icon/relic/101_1.png' },
    { id: '61013', set_id: '101', name: '过客的残绣风衣', rarity: 5, type: 'BODY', max_level: 15, main_affix_id: '53', sub_affix_id: '5', icon: 'icon/relic/101_2.png' },
    { id: '61014', set_id: '101', name: '过客的冥途游履', rarity: 5, type: 'FOOT', max_level: 15, main_affix_id: '54', sub_affix_id: '5', icon: 'icon/relic/101_3.png' },
  ],
}
const relicMainAffixes = ''
const relicSubAffixes = ''
const relicSets = ''

export const starRailData = {
  source,
  characters: decode<Record<string, StarRailCharacter>>(characters),
  characterPromotions: decode<Record<string, StarRailPromotionEntry>>(characterPromotionsData),
  characterSkills: decode<Record<string, StarRailSkill>>(characterSkillsData),
  characterSkillTrees: decode<Record<string, StarRailSkillTree>>(characterSkillTreesData),
  lightCones: decode<Record<string, StarRailLightCone>>(lightConesData),
  lightConePromotions: decode<Record<string, StarRailPromotionEntry>>(lightConePromotionsData),
  lightConeRanks: decode<Record<string, StarRailLightConeRank>>(lightConeRanksData),
  relicMainAffixes: decode(relicMainAffixes),
  relicSubAffixes: decode(relicSubAffixes),
  relics: relicsMetadata,
  relicIcons: {
    '101': ['icon/relic/101_0.png', 'icon/relic/101_1.png', 'icon/relic/101_2.png', 'icon/relic/101_3.png'],
  },
  relicSets: decode(relicSets),
} as const

export function mergeStarRailData(resource: keyof typeof starRailData, value: unknown) {
  const target = starRailData[resource] as unknown as Record<string, unknown>
  if (!target || typeof value !== 'object' || value === null) return false
  Object.assign(target, value)
  return true
}
